const err = $input.first().json;
console.error('[LendLoop Automation Alert] Workflow failed after retries:', JSON.stringify({
  workflowName: err.workflow?.name,
  executionId: err.execution?.id,
  errorMessage: err.execution?.error?.message,
  lastNodeExecuted: err.execution?.lastNodeExecuted,
  timestamp: new Date().toISOString()
}));
return $input.all();
